func minDistance(word1 string, word2 string) int {
	n, m := len(word1), len(word2)
	// 有一个字符串为空串
	if n*m == 0 {
		return n + m
	}
	// DP 数组
	D := make([][]int, n+1)
	for i := range D {
		D[i] = make([]int, m+1)
		D[i][0] = i
	}
	for j := 0; j <= m; j++ {
		D[0][j] = j
	}
	// 计算所有 DP 值
	for i := 1; i <= n; i++ {
		for j := 1; j <= m; j++ {
			left := D[i-1][j] + 1
			down := D[i][j-1] + 1
			leftDown := D[i-1][j-1]
			if word1[i-1] != word2[j-1] {
				leftDown++
			}
			D[i][j] = min(min(left, down), leftDown)
		}
	}
	return D[n][m]
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}
